// raw IndexedDB snapshot with its OWN connection (not the app's reader/exporter): all four stores incl. secret keys, SHA-256 of every audio Blob, all localStorage
const snapRaw = page => page.evaluate(async () => {
  const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
  const db = await new Promise((res, rej) => { const r = indexedDB.open('plainsong'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const o = { tracks: [], playlists: [], kv: [], blobs: [] }, raw = [];
  const tx = db.transaction(['tracks', 'playlists', 'blobs', 'kv'], 'readonly');
  const cur = (n, f) => { const q = tx.objectStore(n).openCursor(); q.onsuccess = () => { const c = q.result; if (c) { f(c); c.continue(); } }; };
  cur('tracks', c => o.tracks.push(c.value)); cur('playlists', c => o.playlists.push(c.value)); cur('kv', c => o.kv.push({ key: c.key, value: c.value })); cur('blobs', c => raw.push({ key: c.key, b: c.value }));
  await new Promise(res => { tx.oncomplete = res; }); db.close();
  for (const x of raw) o.blobs.push({ key: x.key, type: x.b.type, size: x.b.size, sha256: hex(await crypto.subtle.digest('SHA-256', await x.b.arrayBuffer())) });
  o.ls = {}; for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); o.ls[k] = localStorage.getItem(k); }
  return o;
});
const isSecret = k => k.toLowerCase().startsWith('secret:');
// the live DB must equal what the oracle read from the backup: exact records and order, exact audio, secrets = this browser's own, theme by policy
function matchTruth(tag, s, t, secrets, ls) {
  rec(`${tag}: tracks identical to the backup (every field, key order, order)`, J(s.tracks) === J(t.tracks), `${s.tracks.length} vs ${t.tracks.length}`);
  rec(`${tag}: playlists identical (ids order kept)`, J(s.playlists) === J(t.playlists));
  rec(`${tag}: kv (everything but secret: keys) identical, including session and history`, J(s.kv.filter(x => !isSecret(x.key))) === J(t.kv), J(s.kv.filter(x => !isSecret(x.key)).map(x => x.key)) + ' vs ' + J(t.kv.map(x => x.key)));
  rec(`${tag}: ${t.blobs.length} audio entries identical: key, MIME, size, SHA-256 (no old audio left)`, J(s.blobs) === J(t.blobs.map(({ key, type, size, sha256 }) => ({ key, type, size, sha256 }))), `${s.blobs.length} vs ${t.blobs.length}`);
  rec(`${tag}: this browser's own secret: keys are untouched (${secrets.length})`, J(s.kv.filter(x => isSecret(x.key))) === J(secrets), J(s.kv.filter(x => isSecret(x.key))));
  rec(`${tag}: localStorage is exactly ${J(ls)} (theme policy)`, J(Object.fromEntries(Object.entries(s.ls).sort())) === J(Object.fromEntries(Object.entries(ls).sort())), J(s.ls));
}

